import unittest
from shape_match import matches

class ShapeTests(unittest.TestCase):
    def test_dtype_is_part_of_identity(self):
        target = {'op':'matmul','shape':[2,4],'dtype':'bf16','device':'npu'}
        actual = {'op':'matmul','shape':[2,4],'dtype':'fp32','device':'npu'}
        self.assertFalse(matches(target, actual))

if __name__ == '__main__':
    unittest.main()
